<?php
require dirname(__DIR__).'/includes/bootstrap.php'; require_role('admin'); $title=t('Doctor schedules'); $error=null;
$doctors=query('SELECT * FROM doctors ORDER BY name')->fetchAll(); $doctorId=(int)($_GET['doctor'] ?? $doctors[0]['id'] ?? 0);
$doctor=one('SELECT * FROM doctors WHERE id=?',[$doctorId]);
if ($_SERVER['REQUEST_METHOD']==='POST' && $doctor) {
    verify_csrf();
    try {
        $action=$_POST['action'] ?? '';
        if ($action==='save') save_schedule($doctorId,(int)($_POST['weekday']??0),$_POST);
        elseif ($action==='absent') mark_unavailable($doctorId,(string)($_POST['date']??''),(string)($_POST['reason']??''));
        elseif ($action==='remove' || $action==='restore') {
            db()->beginTransaction();
            try {
                one('SELECT id FROM doctors WHERE id=? FOR UPDATE',[$doctorId]);
                if ($action==='remove') query('DELETE FROM weekly_schedules WHERE doctor_id=? AND weekday=?',[$doctorId,(int)($_POST['weekday']??0)]);
                else query('DELETE FROM unavailable_dates WHERE doctor_id=? AND unavailable_date=?',[$doctorId,(string)($_POST['date']??'')]);
                db()->commit();
            } catch(Throwable $e) { db()->rollBack(); throw $e; }
        } else throw new DomainException(t('Unknown action.'));
        flash(t('Schedule updated. Dates already booked retain their saved consultation times.')); redirect('admin/schedules.php?doctor='.$doctorId);
    } catch (DomainException $e) { $error=$e->getMessage(); }
}
$schedules=$doctor?query('SELECT * FROM weekly_schedules WHERE doctor_id=? ORDER BY weekday',[$doctorId])->fetchAll():[];
$editing=isset($_GET['weekday'])?one('SELECT * FROM weekly_schedules WHERE doctor_id=? AND weekday=?',[$doctorId,(int)$_GET['weekday']]):null;
if($error && ($_POST['action']??'')==='save') $editing=$_POST;
$absences=$doctor?query('SELECT * FROM unavailable_dates WHERE doctor_id=? AND unavailable_date>=? ORDER BY unavailable_date',[$doctorId,today()])->fetchAll():[];
require dirname(__DIR__).'/includes/header.php';
?>
<main id="main" class="container section"><div class="section-heading"><div><div class="eyebrow"><?= e(t('SET ONCE. REPEAT WEEKLY.')) ?></div><h1><?= e(t('Doctor schedules')) ?></h1><p class="muted"><?= e(t('Different days, different hours. Upcoming dates appear automatically.')) ?></p></div></div><form method="get" class="filter-bar"><label for="doctor" class="form-label mb-0"><?= e(t('Choose doctor')) ?></label><select id="doctor" name="doctor" class="form-select"><?php foreach($doctors as $d): ?><option value="<?= e($d['id']) ?>" <?= $doctorId===$d['id']?'selected':'' ?>><?= e($d['name']) ?><?= !$d['active']?' ('.e(t($d['archived_at']?'Archived':'Inactive')).')':'' ?></option><?php endforeach; ?></select><button class="btn btn-outline-primary"><?= e(t('View schedule')) ?></button></form><?php if($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif; ?><?php if(!$doctor): ?><div class="empty-state"><?= e(t('Add a doctor before creating a schedule.')) ?></div><?php else: ?><div class="row g-4"><div class="col-xl-4"><form class="panel" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save"><h2><?= e(t($editing?'Edit weekly hours':'Add weekly hours')) ?></h2><label for="weekday" class="form-label"><?= e(t('Working day')) ?></label><select name="weekday" id="weekday" class="form-select mb-3"><?php foreach(weekdays() as $num=>$name): ?><option value="<?= $num ?>" <?= (int)($editing['weekday']??0)===$num?'selected':'' ?>><?= e(t($name)) ?></option><?php endforeach; ?></select><div class="row g-3"><?php foreach(['booking_open'=>['Booking opens','09:00'],'booking_close'=>['Booking cutoff','16:00'],'consultation_start'=>['Consultation starts','18:30'],'consultation_end'=>['Consultation ends','21:30']] as $key=>$field): ?><div class="col-6"><label class="form-label" for="<?= $key ?>"><?= e(t($field[0])) ?></label><input class="form-control" type="time" id="<?= $key ?>" name="<?= $key ?>" value="<?= e(substr($editing[$key]??$field[1],0,5)) ?>" required></div><?php endforeach; ?></div><label class="form-label mt-3" for="duration"><?= e(t('Minutes per consultation')) ?></label><input class="form-control" type="number" id="duration" name="duration_minutes" min="1" max="120" value="<?= e($editing['duration_minutes']??5) ?>" required><p class="form-text"><?= e(t('Capacity is calculated automatically. Saving the same weekday updates it without duplicates.')) ?></p><button class="btn btn-primary mt-2"><?= e(t('Save weekly hours')) ?></button></form><form class="panel mt-4" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="absent"><h2><?= e(t('Mark a date unavailable')) ?></h2><label for="absence" class="form-label"><?= e(t('Date')) ?></label><input class="form-control mb-3" type="date" id="absence" name="date" min="<?= today() ?>" required><label for="reason" class="form-label"><?= e(t('Reason (staff only)')) ?></label><input class="form-control mb-3" id="reason" name="reason" maxlength="200" placeholder="<?= e(t('e.g. On leave')) ?>"><p class="form-text"><?= e(t('If appointments exist, contact patients and cancel them in the queue first.')) ?></p><button class="btn btn-outline-primary"><?= e(t('Mark unavailable')) ?></button></form></div><div class="col-xl-8"><div class="panel"><h2><?= e($doctor['name']) ?> <span class="muted h6"><?= e(t('· Weekly schedule')) ?></span></h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th><?= e(t('Day')) ?></th><th><?= e(t('Booking hours')) ?></th><th><?= e(t('Consultations')) ?></th><th><?= e(t('Capacity')) ?></th><th></th></tr></thead><tbody><?php foreach($schedules as $s): ?><tr><td><strong><?= e(weekday_label((int)$s['weekday'])) ?></strong></td><td><?= e(time_label($s['booking_open'])) ?><small class="d-block muted"><?= e(t('schedule.until',['time'=>time_label($s['booking_close'])])) ?></small></td><td><?= e(time_label($s['consultation_start'])) ?><small class="d-block muted"><?= e(t('schedule.until',['time'=>time_label($s['consultation_end'])])) ?></small></td><td><?= capacity($s) ?><small class="d-block muted"><?= e(t('schedule.minutes',['minutes'=>$s['duration_minutes']])) ?></small></td><td><a href="?doctor=<?= $doctorId ?>&amp;weekday=<?= e($s['weekday']) ?>"><?= e(t('Edit')) ?></a><form class="mt-2" method="post" data-confirm="<?= e(t('Remove this recurring weekday? Dates already booked keep their saved schedule.')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="remove"><input type="hidden" name="weekday" value="<?= e($s['weekday']) ?>"><button class="btn-link danger-link"><?= e(t('Remove')) ?></button></form></td></tr><?php endforeach; ?><?php if(!$schedules): ?><tr><td colspan="5" class="py-4 muted"><?= e(t('No recurring hours yet.')) ?></td></tr><?php endif; ?></tbody></table></div><p class="notice small mb-0"><?= e(t('Once a date has appointments, its schedule is saved. Changes here apply to dates without bookings; existing tokens and estimates stay the same.')) ?></p></div><div class="panel mt-4"><h2><?= e(t('Upcoming dates')) ?> <span class="muted h6"><?= e(t('schedule.next_days',['days'=>$config['booking_days']])) ?></span></h2><div class="upcoming-grid"><?php foreach(upcoming_dates($doctorId) as $date=>$state): ?><div><strong><?= e(short_date($date)) ?></strong><small><?= e($state['label']) ?></small><?php if(isset($state['schedule'])): ?><span><?= e(t('booking.date_option',['time'=>time_label($state['schedule']['consultation_start']),'count'=>$state['remaining']??0])) ?></span><?php endif; ?></div><?php endforeach; ?></div></div><?php if($absences): ?><div class="panel mt-4"><h2><?= e(t('Unavailable dates')) ?></h2><?php foreach($absences as $absence): ?><div class="d-flex justify-content-between gap-3 border-bottom py-3"><div><strong><?= e(date_label($absence['unavailable_date'])) ?></strong><small class="d-block muted"><?= e($absence['reason']) ?></small></div><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="restore"><input type="hidden" name="date" value="<?= e($absence['unavailable_date']) ?>"><button class="btn btn-light btn-sm"><?= e(t('Restore')) ?></button></form></div><?php endforeach; ?></div><?php endif; ?></div></div><?php endif; ?></main><?php require dirname(__DIR__).'/includes/footer.php'; ?>
